+#define DL(W, N) if (!ok && dn_rt == 0 && dn_warps == W && (M > 8) == (N == 2)) { ok = true; moe_down_fp4_loop<H, I, TOPK, W, N><<<H / 16, W * 32, 0, st>>>(ap, ep, wt.data_ptr<float>(), u8(w2), u8(s2), g2.data_ptr<float>(), u8(sh2), u8(shs2), shg2.data_ptr<float>(), yp, M); }
